<?php require __DIR__.'/bootstrap.php'; if(getenv('LEDGER_BACKUP_EXECUTE')!=='1') throw new RuntimeException('Set LEDGER_BACKUP_EXECUTE=1 only in an approved operator session.'); $c=ledger_config(); $dir=$c->get('backup_path'); if(!is_dir($dir)&&!mkdir($dir,0700,true)) throw new RuntimeException('Backup path unavailable.'); $stamp=gmdate('Ymd_His'); $file=$dir.'/ledger_'.$stamp.'.sql'; $defaults=tempnam(sys_get_temp_dir(),'ledger-mycnf-'); file_put_contents($defaults,"[client]\nhost={$c->get('db_host')}\nport={$c->get('db_port')}\nuser={$c->get('db_user')}\npassword={$c->get('db_password')}\n"); @chmod($defaults,0600); $command=['mysqldump','--defaults-extra-file='.$defaults,'--single-transaction','--skip-lock-tables',$c->get('db_name')]; $proc=proc_open($command,[1=>['file',$file,'w'],2=>['pipe','w']],$pipes); if(!is_resource($proc)) throw new RuntimeException('Backup process did not start.'); $stderr=stream_get_contents($pipes[2]); $exit=proc_close($proc); @unlink($defaults); if($exit!==0) throw new RuntimeException('Backup failed.'); $hash=hash_file('sha256',$file); file_put_contents($file.'.sha256',$hash.'  '.basename($file).PHP_EOL); echo basename($file)."\n";
